<section class="split-workspace curriculum-workspace"><form class="panel quick-form" method="post" action="<?= e(url('courses')) ?>"><?= csrf_field() ?><p class="eyebrow">Programme course structure</p><h2>Add or update course</h2><label>Programme / branch<select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $programme):?><option value="<?= (int)$programme['id'] ?>"><?= e($programme['code'].' - '.$programme['name']) ?></option><?php endforeach;?></select></label><div class="course-form-pair"><label>Course level<select name="course_level" required><option value="UG">UG</option><option value="PG">PG</option></select></label><label>Course year<select name="course_year" required><?php for($i=1;$i<=6;$i++):?><option value="<?= $i ?>">Year <?= $i ?></option><?php endfor;?></select></label></div><label>Semester<select name="semester" required><option value="">Select semester</option><?php for($i=1;$i<=12;$i++):?><option value="<?= $i ?>">Semester <?= $i ?></option><?php endfor;?></select></label><label>Course code<input name="code" placeholder="CS-101" maxlength="40" required></label><label>Course name<input name="name" placeholder="Programming Fundamentals" required></label><div class="course-form-pair"><label>Course credits<input name="course_credits" type="number" min="0" max="99.9" step="0.5" value="4" required></label><label>Category<select name="category"><option value="core">Core</option><option value="elective">Elective</option><option value="common">Common</option><option value="bridge">Bridge</option><option value="back_paper">Back paper</option><option value="other">Other</option></select></label></div><div class="course-form-pair"><label>Mid-sem exam hours<input name="mid_sem_hours" type="number" min="0.5" max="6" step="0.5" value="1.5" required></label><label>End-sem exam hours<input name="end_sem_hours" type="number" min="0.5" max="8" step="0.5" value="3" required></label></div><label>Scheduling priority<input name="subject_priority" type="number" min="1" max="100" value="50" required><small id="course-guidance">1 is scheduled earliest; 100 is lowest priority.</small></label><button class="primary-button">Save course structure</button></form>
<section class="panel table-panel curriculum-register"><form class="table-toolbar curriculum-filters" method="get"><strong>Course structure register</strong><select name="programme"><option value="">All programmes</option><?php foreach($programmes as $programme):?><option value="<?= e($programme['code']) ?>" <?= $programmeFilter===$programme['code']?'selected':'' ?>><?= e($programme['code']) ?></option><?php endforeach;?></select><select name="semester"><option value="0">All semesters</option><?php for($i=1;$i<=12;$i++):?><option value="<?= $i ?>" <?= $semesterFilter===$i?'selected':'' ?>>Semester <?= $i ?></option><?php endfor;?></select><button class="secondary-button">Filter</button></form><div class="table-scroll"><table><thead><tr><th>Programme / branch</th><th>Course</th><th>Level / year</th><th>Semester</th><th>Credits</th><th>Exam duration</th><th>Category</th><th>Priority</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php $shown=0;foreach($courses as $course):if(($programmeFilter!==''&&$course['programme_code']!==$programmeFilter)||($semesterFilter&&$semesterFilter!==(int)$course['semester']))continue;$shown++;?><tr><td><strong><?= e($course['programme_code']) ?></strong><small class="cell-note"><?= e($course['programme_name']) ?></small></td><td><strong><?= e($course['code']) ?></strong><small class="cell-note"><?= e($course['name']) ?></small></td><td><strong><?= e($course['course_level']) ?></strong><small class="cell-note">Year <?= (int)$course['course_year'] ?></small></td><td><span class="semester-chip">Semester <?= (int)$course['semester'] ?></span></td><td><?= e(number_format((float)$course['course_credits'],1)) ?></td><td><strong>Mid: <?= e(number_format((int)$course['mid_sem_duration_minutes']/60,1)) ?> h</strong><small class="cell-note">End: <?= e(number_format((int)$course['end_sem_duration_minutes']/60,1)) ?> h</small></td><td><?= e(ucwords(str_replace('_',' ',$course['category']))) ?></td><td><span class="priority-chip"><?= (int)$course['subject_priority'] ?></span></td><td><span class="status-label <?= e($course['status']) ?>"><?= e(ucfirst($course['status'])) ?></span></td><td><form method="post" action="<?= e(url('courses/curriculum/'.(int)$course['mapping_id'].'/delete')) ?>" data-confirm="<?= e('Remove '.$course['code'].' from '.$course['programme_code'].' Semester '.$course['semester'].'? Other branches are unchanged. Reimporting can restore an unused mapping.') ?>" onsubmit="return window.confirm(this.dataset.confirm)"><?= csrf_field() ?><button class="secondary-button" type="submit" aria-label="<?= e('Delete '.$course['code'].' from '.$course['programme_code'].' Semester '.$course['semester']) ?>"><i class="ti ti-trash" aria-hidden="true"></i> Delete</button></form></td></tr><?php endforeach;?><?php if(!$shown):?><tr><td colspan="10" class="empty-table-cell">No courses match this programme and semester.</td></tr><?php endif;?></tbody></table></div></section></section>
